reference_solution:
def land_perimeter(grid):
    if not grid or not grid[0]: return 0
    perimeter = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                perimeter += 4
                if r and grid[r-1][c]: perimeter -= 2
                if c and grid[r][c-1]: perimeter -= 2
    return perimeter

